import{_ as o,c as r,o as n,ae as s}from"./chunks/framework.D6wf4lw6.js";const q=JSON.parse('{"title":"滿配內部填充與聲學組件全解析","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/深度定制/满配声音包.md","filePath":"zh-HK/深度定制/满配声音包.md"}'),e={name:"zh-HK/深度定制/满配声音包.md"};function g(l,t,a,d,i,u){return n(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="滿配內部填充與聲學組件全解析" tabindex="-1">滿配內部填充與聲學組件全解析 <a class="header-anchor" href="#滿配內部填充與聲學組件全解析" aria-label="Permalink to &quot;滿配內部填充與聲學組件全解析&quot;">​</a></h1><blockquote><p><strong>核心要點</strong>：填充物的終極目的是 <strong>&quot;淨化&quot;與&quot;塑造&quot;聲音</strong>。它們透過吸收不必要的振動和雜音，並精細調整振動的傳遞特性，讓軸體本身產生的乾淨、悅耳的基礎聲音得以清晰地展現，並朝著你喜愛的音色方向演變，從而極大地提升打字的聽覺體驗。</p></blockquote><h2 id="核心組件比較表" tabindex="-1">核心組件比較表 <a class="header-anchor" href="#核心組件比較表" aria-label="Permalink to &quot;核心組件比較表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">零件名稱</th><th style="text-align:left;">位置</th><th style="text-align:left;">主要作用</th><th style="text-align:left;">常見材質與特性</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>軸上墊</strong></td><td style="text-align:left;">鍵帽與軸體上蓋之間</td><td style="text-align:left;">1. <strong>消除鍵帽雜音</strong>：填滿鍵帽與軸心柱之間的空隙，消除晃動聲。 <br>2. <strong>微調觸感</strong>：使觸底感覺略微更柔和。</td><td style="text-align:left;">薄片狀的Poron、矽膠或鐵氟龍，硬度較高，對聲音影響較小。</td></tr><tr><td style="text-align:left;"><strong>夾心棉</strong></td><td style="text-align:left;">定位板與PCB板之間</td><td style="text-align:left;">1. <strong>消除空腔音</strong>：吸收定位板與PCB之間空腔的振動與迴聲。 <br>2. <strong>統一聲音</strong>：使各位置按鍵聲音一致。 <br>3. <strong>過濾高頻噪音</strong>：讓音色更純粹、更沉悶。</td><td style="text-align:left;"><strong>PORON</strong>：慢回彈，壽命長，效果最佳。 <br><strong>IXPE</strong>：性價比高，效果良好。 <br><strong>矽膠</strong>：重量大，吸音效果好，能增重。</td></tr><tr><td style="text-align:left;"><strong>軸下墊</strong></td><td style="text-align:left;">PCB與軸體之間</td><td style="text-align:left;">1. <strong>消除軸體雜音</strong>：吸收軸體內部金屬彈片音和觸底撞擊PCB的高頻噪音（&quot;叮&quot;聲）。 <br>2. <strong>塑造核心音色</strong>：是打造&quot;Hifi&quot;音的關鍵。 <br>3. <strong>軟化觸底</strong>：使觸底感更&quot;肉&quot;。</td><td style="text-align:left;"><strong>PORON/IXPE</strong>：能極致地消除雜音，讓軸體聲音更乾淨、集中。</td></tr><tr><td style="text-align:left;"><strong>聲優膜</strong></td><td style="text-align:left;">貼附於軸下墊和夾心棉之間</td><td style="text-align:left;">1. <strong>進一步提純音色</strong>：作為軸下墊的補充，通過不同材質或厚度，<strong>微調</strong>觸底音的音色和頻率，使其更沉悶或更清脆。 <br>2. <strong>改變觸底硬度</strong>：提供比軸下墊更細微的觸底手感變化。</td><td style="text-align:left;"><strong>PE</strong></td></tr><tr><td style="text-align:left;"><strong>軸座棉</strong></td><td style="text-align:left;">PCB底部，覆蓋在軸座之上</td><td style="text-align:left;"><strong>補充吸音</strong>：從底部吸收透過PCB的殘餘振動和特定頻率的噪音。</td><td style="text-align:left;">較薄的PORON或IXPE。注意可能會影響軸座安裝。</td></tr><tr><td style="text-align:left;"><strong>聲優背膜</strong></td><td style="text-align:left;">貼附於軸座棉與底棉之間</td><td style="text-align:left;">1. <strong>消除PCB板顫</strong>：抑制PCB本身因振動產生的細微&quot;嗡&quot;聲。 <br>2. <strong>補充高頻吸收</strong>：從背面進一步過濾通過PCB孔的殘餘高頻噪音。 <br>3. <strong>改變PCB振動特性</strong>：使PCB整體更&quot;硬&quot;，從而影響傳遞到底棉的振動頻率。</td><td style="text-align:left;"><strong>PE</strong></td></tr><tr><td style="text-align:left;"><strong>底棉</strong></td><td style="text-align:left;">鍵盤PE外殼底部，PCB之下</td><td style="text-align:left;">1. <strong>消除最大空腔音</strong>：填充PCB與底殼間的巨大空腔，消除低沉、空洞的迴響。 <br>2. <strong>增加穩重感</strong>：使鍵盤敲擊時更紮實。</td><td style="text-align:left;"><strong>PORON</strong>：效果最好，壽命長。 <br><strong>消音棉/EVA</strong>：成本低，但可能老化。 <br><strong>矽膠</strong>：效果極佳，能大幅增重，需客製化。</td></tr></tbody></table><h2 id="詳細解讀與系統層級影響" tabindex="-1">詳細解讀與系統層級影響 <a class="header-anchor" href="#詳細解讀與系統層級影響" aria-label="Permalink to &quot;詳細解讀與系統層級影響&quot;">​</a></h2><h3 id="_1-作用層級與聲音包概念" tabindex="-1">1. 作用層級與聲音包概念 <a class="header-anchor" href="#_1-作用層級與聲音包概念" aria-label="Permalink to &quot;1. 作用層級與聲音包概念&quot;">​</a></h3><p>可以將這些組件理解為一個協同工作的 <strong>&quot;聲音包&quot;</strong> 或 <strong>&quot;消音系統&quot;</strong>：</p><ul><li><strong>基礎淨化層（消除結構噪音）</strong>：<strong>底棉</strong> 和 <strong>夾心棉</strong>。它們負責處理因鍵盤物理結構產生的<strong>空腔音</strong>和<strong>迴聲</strong>，解決了聲音&quot;塑膠感&quot;和&quot;空洞感&quot;的基礎問題。</li><li><strong>核心塑造層（消除聲源噪音）</strong>：<strong>軸下墊</strong> 和 <strong>聲優膜</strong>。它們直接作用於聲音的源頭－軸體，負責消除軸體自身的<strong>金屬雜音</strong>，並透過材質和厚度來<strong>主動塑造</strong>核心的按鍵音色，是&quot;麻將音&quot;、&quot;石子音&quot;的靈魂所在。</li><li><strong>微調最佳化層（精細抑振）</strong>：<strong>聲優背膜</strong>、<strong>軸座棉</strong> 和 <strong>軸上墊</strong>。它們對整體體驗進行精細調整，解決PCB板振、軸座雜音和鍵帽晃動等細節問題。</li></ul><h3 id="_2-重要注意事項" tabindex="-1">2. 重要注意事項 <a class="header-anchor" href="#_2-重要注意事項" aria-label="Permalink to &quot;2. 重要注意事項&quot;">​</a></h3><ul><li><strong>過猶不及</strong>：填充過厚或過硬的棉會<strong>增加鍵盤內部的壓力</strong>，可能導致PCB彎曲、軸體引腳接觸不良、甚至使Gasket結構的&quot;軟彈&quot;手感消失。務必選擇合適厚度的填充物。</li><li><strong>從上到下順序</strong>：通常的安裝順序是：<strong>軸上墊 → 定位板 → 夾心棉 → 聲優膜 → 軸下墊 → PCB電路板 → 軸座棉 → 聲優背膜 → 底棉</strong>。</li><li><strong>聲音是系統工程</strong>：填充物只是&quot;淨化&quot;與&quot;塑造&quot;聲音，而鍵盤的最終音色是由 <strong>軸體（核心聲源） + 定位板（調音板） + 填充物（消音系統） + 鍵帽（共鳴腔） + 結構（傳播路徑）</strong> 共同決定的。</li></ul>',10)])])}const x=o(e,[["render",g]]);export{q as __pageData,x as default};
